"""Writes AnnouncerClips.java: every clip key with its real duration in seconds."""
import os, subprocess, sys
clips, out = sys.argv[1], sys.argv[2]
rows = []
for f in sorted(os.listdir(clips)):
    if f.endswith(".ogg"):
        d = float(subprocess.run(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0",
                                  os.path.join(clips, f)], capture_output=True, text=True).stdout)
        rows.append((f[:-4], d))
with open(out, "w") as w:
    w.write("package com.rcboat.racing;\n\nimport java.util.HashMap;\n\n"
            "/** Generated by tools/announcer/make_table.py: announcer clip keys and durations (seconds). */\n"
            "final class AnnouncerClips {\n    static final HashMap<String, Float> DURATION = new HashMap<>();\n\n    static {\n")
    for k, d in rows:
        w.write('        DURATION.put("%s", %.2ff);\n' % (k, d))
    w.write("    }\n\n    private AnnouncerClips() {}\n}\n")
print(len(rows), "clips, total %.0f s, longest %.2f s" % (sum(d for _, d in rows), max(d for _, d in rows)))
